INSERT INTO transfer_targets VALUES(10,'AVL','2026-summer','Modou Kéba Cissé','시세','시세',57,1944705,'LASK → Aston Villa','CB','RCB','CONFIRMED',NULL,'001100013201476027X812666',60.89999999999999858,31.19999999999999929,29,7.099999999999999645,'cb_defender','Balanced','cb_bpd','Aggressive',0.8830000000000000071,'CONFIRMED incoming: pre-contract signed summer 2025, joins for 2026/27 after a season at LASK. Measured: right-of-centre CB (60.9,31.2), Ball-Playing Defender/Aggressive fit 0.89 — same fit family as Konsa (0.88). Natural RCB cover/heir; Austrian Bundesliga level caveat. [2026-07-15 재확인] RotoWire: 공식 합류 확인(사전계약, LASK에서 2026년 여름 발효). [2026-07-15 3축+스탯 — 유지] 6경기: kp 0·xA .01·듀얼 3.8·태클 1.5·패스 84% — 진전 산출 없는 수비형, cb_defender/Balanced 처방 유지(움직임은 bpd/Aggressive .89로 콘사형 스텝아웃 — 기능축 우선). LASK 리그 수준 캐비앗. [2026-07-28 FC26 통합 확인] 숙련 cb_defender+·cb_stopper+ — bpd 마커 없음, 기능축 처방(cb_defender/Balanced)을 FC26이 지지 — 확정.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 29경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(13,'AVL','2026-summer','Alysson','알리송',NULL,59,1631879,'Aston Villa (2026-01, Grêmio €10M)','RW','RM','OWNED',NULL,'001331015X001370003500013',83.20000000000000284,59.70000000000000284,22,6.879999999999999894,'wm_winger','Balanced','wm_widemid','Build-Up',0.8329999999999999627,'ALREADY OWNED: joined from Grêmio for €10M in January 2026; young (2006) right winger not yet in the analysis roster. Measured: genuine wide-right (83.2,59.7) — the squad''s only natural touchline RW; fit Inside Forward/Balanced 0.85. Prescription Winger/Attack to use his width+pace profile distinct from McGinn/Bowen half-space types. [2026-07-15 3축+스탯 — 유지] 6경기: xG .10·xA .03·kp .3·듀얼 3.7·드리블 1.0 — 창조 산출 미성숙 직선 윙어, winger/Attack 처방 유지(움직임 최근접은 insidefwd/Balanced .847). [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .839, 침투 서명 전방 0.54·자기진영 0.23(하지무사·음바예보다 낮음 = 침투 빈도 열위), 터치라인 열 0.60 = 스쿼드 유일 천연 터치라인 RW. 함의: 브리프를 부분 충족하는 보유 자원이라 "우측이 절대 공백은 아니다"는 협상 레버리지. 19세로 주전 고정은 리스크.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 22경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(30,'AVL','2026-summer','Tammy Abraham','타미 아브라함',NULL,60,610766,'Aston Villa','ST','ST','OWNED',NULL,'239324777256X732212211410',47.39999999999999858,59.0,25,6.950000000000000177,'st_target','Attack','st_false9','Attack',0.6430000000000000159,'ALREADY OWNED: 2026-01-27 베식타슈에서 ~£18m로 빌라 복귀(1일 만에 재이적), 그 시즌 유로파리그 우승. 여름 루머 대상이 아니라 보유 선수(알리송과 동일 케이스) — 사용자 요청으로 OWNED ST 옵션으로 편입. 실측(반시즌 통틀어 45분+ 4경기 전부 ST): 중앙-약간좌측·깊은 풋프린트 (47.4,59.0), 평균 6.85. 최근접 st_false9/Attack 0.52 — 왓킨스(st_advanced 자기커널)·기라시 0.80·브로베이 0.75·파르도 0.87보다 명확히 낮음. 처방은 타깃/홀드업 아키타입 반영 st_target/Attack. 표본 캐비앳: 왓킨스의 로테이션 백업이라 45분+ 경기가 반시즌 4경기뿐이고 전부 교체 출전(추격 상황 드롭) → 깊은 편향된 풋프린트, 선발 표본 아님. [2026-07-15 3축+스탯 — 유지] 6경기: xG .25·3골·kp 1.0·드리블 0 — 타깃형 피니셔, st_target/Attack(공중 플랜B, obs#19) 유지.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 25경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(77,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg','CM','LDM','CONFIRMED',NULL,'33423X9565897636965322311',43.60000000000000142,51.79999999999999716,56,7.200000000000000177,'dm_dlp','Roaming','dm_dlp','Roaming',0.7129999999999999672,'완전 box-to-box, 중앙 전역 커버(온아나 대체). 실측 6경기(분데스리가, 363pt) 중심 tool(44,52). 커널 fit LDM dm_dlp/Roaming 0.812 (RDM는 0.544로 약함 → 좌중앙 성향, LDM 전용). 평균 7.62 최상. [2026-07-14 확정] 빌라 합류 확정(사용자 확인). [2026-07-15 재확인] Romano "here we go": €60m+ 구두합의, 개인조건 완료. 뉴캐슬 £49m 구두합의를 히잭. 아직 공식 발표(메디컬) 전 단계. [2026-07-15 3축+스탯 — 유지] 6경기: 듀얼 7.5(후보군 1위)·xG .18·xA .16·태클 1.8·평점 7.40 — 박투박+창조 겸비(오나나 공백 임무에도 부합), dlp/Roaming 유지. [2026-07-17 재확인] 메디컬 완료(7/16), Romano "몇 시간 내 발표". Visit Rwanda 스폰서 관련 잡음(DRC 가족사) 해소, 5년 계약 — 클럽 레코드 £50m+. [2026-07-18 재확인] 공식 발표 완료(7/17 저녁) — £59.5m(€70m) 클럽 레코드, 장기계약. 뉴캐슬 하이잭 최종 성사. [2026-07-21 멀티포지션] CAM(대표팀 전진 실측 0.817)·LM(재배치 0.700) 행 추가 — 슬롯별 별도 그리드 참조. [2026-07-28 FC26 통합 확인] LDM: 숙련 dm_dlp+·cm_dlp+가 처방과 일치 — 확정. 테크니컬 PS·드리블85.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 56경기. 클럽(프라이부르크) 44경기 통합 — 딥 역할 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(91,'AVL','2026-summer','João Palhinha',NULL,'팔리냐',75,364612,'Bayern Munich','DM','LDM','DEAD (벤피카 이적 합의 — 바이에른-벤피카 €15m+€5m 클럽 간 합의, 2026-08-20 SIC/O Jogo)','2026-08-20','012113536536797368X712431',57.0799999999999983,44.96000000000000085,34,7.160000000000000142,'dm_dlp','Roaming','dm_dlp','Roaming',0.7089999999999999636,'[2026-08-21 DEAD 확정 + 복원 트리거 폐기] ⭐ 목적지가 제3자로 결론났다. **바이에른-벤피카 합의 €15m + €5m 목표 보너스**(SIC Notícias 08-20) / Maisfutebol은 €14m+€5m, 최대 €20m·현실 회수 €18~19m로 적는다 — 금액은 **단일값 미채택**. 선수 측은 **4시즌 계약 · 순연봉 약 €2.5m**에 벤피카와 이해가 있고, 벤피카 총 투자는 임금 포함 약 €34m이다. **마르쿠 실바 재결합**(풀럼 시절)이 동력. ⭐⭐ 결정적으로 **선수가 빌라를 직접 거절했다** — 「뉴캐슬을 먼저, 그다음 아스톤 빌라를 거절하고 벤피카를 1순위로 뒀다」. ⭐ Romano(1티어) 08-20: 팔리냐의 **PL 이적은 이제 가능성이 낮다**, **바이에른이 빌라의 임대안을 거절하고 완전 매각만 원한다**. ⇒ 08-15 「Eberl 연화」 서술보다 최신이고 방향이 반대다. ⭐⭐ **복원 트리거 문구를 폐기한다.** 기존 문구(⑴ 빌라 정식 오퍼 ⑵ 구단 간 합의)는 08-19에 문자적으로 발동했는데 실체는 **거절된 오퍼**였고 08-20 벤피카 합의로 24시간 내 소멸했다 — 「오퍼의 존재」가 아니라 **「빌라 쪽 오퍼가 수락되었는가」**를 봐야 했다. 재정의: **복원 = ⑴ 벤피카 딜이 붕괴하고 ⑵ 1티어가 빌라-바이에른 「합의(agreement)」 또는 메디컬을 보도**할 때에 한한다. 거절된 오퍼·재개된 협상·감독 발언 연화는 복원 근거가 아니다. [대체재] 빌라 DM 결손은 실재한다 — 오나나 ACL 시즌아웃 + 주앙 고메스 종아리 부상(개막 결장). 신규 대안 후보 **Youssouf Fofana(밀란, €25m 대역)**가 등장했으나 원출처 Schira 2티어 단독 + 팰리스 경쟁이라 MEDIUM(미등재).','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten ; Fabrizio Romano 2026-08-12 via reddit.com/r/PrimeiraLiga/comments/1vmjlgr/ · Plettenberg/Sky Sport DE 2026-08-12 (https://www.bavarianfootballworks.com/bayern-munich-transfer-news-rumors/242430/) ; Fabrizio Romano(1티어) 2026-08-14 https://x.com/FabrizioRomano/status/2088212008759869662 ; Get German Football News 2026-08-14 https://www.getfootballnewsgermany.com/2026/joao-palhinhas-aston-villa-off/ ; bulinews 2026-08-14 https://bulinews.com/bayern-confirm-talks-aston-villa-for-palhinha-broken-down ; Football365 2026-08-14 ; Marca Diego Picó(2티어) 2026-08-14 via https://footballplace.co.uk/joao-palhinha-newcastle-transfer-aston-villa/ ; Bavarian Football Works 2026-08-14 ; Kicker 경유 에베를 원문 재확인 ; TeamTalk(3티어) 2026-08-15 21:13 UK https://www.teamtalk.com/newcastle-united/newcastle-former-tottenham-star-aston-villa-target-transfer-hijack-threat','마감: 바이에른 축은 「Die Deadline ist der 1. September um 20 Uhr」(독일어 원문). ⚠️ 벤피카 딜의 공식 발표는 미확인 — 「합의」 단계이고 선수가 바이에른과 재무 정산을 마쳐야 한다(계약 2028).');
INSERT INTO transfer_targets VALUES(92,'AVL','2026-summer','João Palhinha',NULL,'팔리냐',75,364612,'Bayern Munich','DM','RDM','DEAD (벤피카 이적 합의 — 바이에른-벤피카 €15m+€5m 클럽 간 합의, 2026-08-20 SIC/O Jogo)','2026-08-20','012113536536797368X712431',57.0799999999999983,44.96000000000000085,34,7.160000000000000142,'dm_dlp','Roaming','dm_dlp','Roaming',0.7860000000000000319,'[2026-08-21 DEAD 확정 + 복원 트리거 폐기] ⭐ 목적지가 제3자로 결론났다. **바이에른-벤피카 합의 €15m + €5m 목표 보너스**(SIC Notícias 08-20) / Maisfutebol은 €14m+€5m, 최대 €20m·현실 회수 €18~19m로 적는다 — 금액은 **단일값 미채택**. 선수 측은 **4시즌 계약 · 순연봉 약 €2.5m**에 벤피카와 이해가 있고, 벤피카 총 투자는 임금 포함 약 €34m이다. **마르쿠 실바 재결합**(풀럼 시절)이 동력. ⭐⭐ 결정적으로 **선수가 빌라를 직접 거절했다** — 「뉴캐슬을 먼저, 그다음 아스톤 빌라를 거절하고 벤피카를 1순위로 뒀다」. ⭐ Romano(1티어) 08-20: 팔리냐의 **PL 이적은 이제 가능성이 낮다**, **바이에른이 빌라의 임대안을 거절하고 완전 매각만 원한다**. ⇒ 08-15 「Eberl 연화」 서술보다 최신이고 방향이 반대다. ⭐⭐ **복원 트리거 문구를 폐기한다.** 기존 문구(⑴ 빌라 정식 오퍼 ⑵ 구단 간 합의)는 08-19에 문자적으로 발동했는데 실체는 **거절된 오퍼**였고 08-20 벤피카 합의로 24시간 내 소멸했다 — 「오퍼의 존재」가 아니라 **「빌라 쪽 오퍼가 수락되었는가」**를 봐야 했다. 재정의: **복원 = ⑴ 벤피카 딜이 붕괴하고 ⑵ 1티어가 빌라-바이에른 「합의(agreement)」 또는 메디컬을 보도**할 때에 한한다. 거절된 오퍼·재개된 협상·감독 발언 연화는 복원 근거가 아니다. [대체재] 빌라 DM 결손은 실재한다 — 오나나 ACL 시즌아웃 + 주앙 고메스 종아리 부상(개막 결장). 신규 대안 후보 **Youssouf Fofana(밀란, €25m 대역)**가 등장했으나 원출처 Schira 2티어 단독 + 팰리스 경쟁이라 MEDIUM(미등재).','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten ; Fabrizio Romano 2026-08-12 via reddit.com/r/PrimeiraLiga/comments/1vmjlgr/ · Plettenberg/Sky Sport DE 2026-08-12 (https://www.bavarianfootballworks.com/bayern-munich-transfer-news-rumors/242430/) ; Fabrizio Romano(1티어) 2026-08-14 https://x.com/FabrizioRomano/status/2088212008759869662 ; Get German Football News 2026-08-14 https://www.getfootballnewsgermany.com/2026/joao-palhinhas-aston-villa-off/ ; bulinews 2026-08-14 https://bulinews.com/bayern-confirm-talks-aston-villa-for-palhinha-broken-down ; Football365 2026-08-14 ; Marca Diego Picó(2티어) 2026-08-14 via https://footballplace.co.uk/joao-palhinha-newcastle-transfer-aston-villa/ ; Bavarian Football Works 2026-08-14 ; Kicker 경유 에베를 원문 재확인 ; TeamTalk(3티어) 2026-08-15 21:13 UK https://www.teamtalk.com/newcastle-united/newcastle-former-tottenham-star-aston-villa-target-transfer-hijack-threat','마감: 바이에른 축은 「Die Deadline ist der 1. September um 20 Uhr」(독일어 원문). ⚠️ 벤피카 딜의 공식 발표는 미확인 — 「합의」 단계이고 선수가 바이에른과 재무 정산을 마쳐야 한다(계약 2028).');
INSERT INTO transfer_targets VALUES(95,'AVL','2026-summer','João Gomes','주앙 고메스','고메스',56,1015267,'Wolverhampton','DM/CM','LDM','CONFIRMED',NULL,'11111794665X6647968421221',47.0,47.10000000000000142,39,6.769999999999999574,'dm_dlp','Roaming','dm_dlp','Roaming',0.7630000000000000115,unistr('틸레만스 대체 영입 — 클럽간 합의(초기 £34.6m+애드온 £4.3m, 총 ~£38m), 금주 메디컬 예정. 아틀레티코행이 멘데스-구단 갈등으로 결렬된 것을 빌라가 인터셉트. [2026-07-17 실측+3축] 최근 6경기(45분+): 태클 3.7·듀얼 7.0·kp .3·xA .04 — 기능=순수 볼위너+박투박 엔진(카마라형). 움직임 최근접 dlp/Roaming .797(LDM — 우측 배치 .638로 좌측 우세). 기능축 우선(obs#31)으로 처방 dm_holding/Ball-Winning. [2026-07-18 재확인] 메디컬 금요일(7/17) 진행 — 포르투갈 캠프 이탈·귀국 확인, 개인조건 2031년 계약 합의(Schira). 공식 발표 임박. [2026-07-28 FC26 통합 확인] 기능축 우선 처방(dm_holding/Ball-Winning) 유지. 캐비앗: FC26 숙련은 boxcrasher/widehalf/dlp/cm_dlp — holding 마커 없음. 압박검증·슬라이딩태클 PS는 볼위닝 기능 지지. [2026-07-29 홀딩 처방 재검증 — 유지 확정] 현행 커널 재검산: dlp/Roaming .797 정확 재현(stale 아님), holding/Ball-Winning은 .45로 움직임 불일치. 그러나 ①실측 홀딩 동료와 직접 유사 — 온아나 그리드 .835/카마라 .805 (둘 다 움직임 코사인은 dlp .87이었으나 기능축으로 holding 처방된 동일 패턴, obs#32) ②기능=창조 전무(kp .3·xA .04) — dlp 지시는 전개 산출 없는 선수에게 공급 책임 부여하는 모순 ③요구역할=카마라 장기부상 중 앵커 대체+obs#27 블록 전제. 3축 모두 holding 지지 → dm_holding/Ball-Winning 유지. 숙련 캐비앗 대응: holding 미숙련 페널티 확인 시 차선은 dm_boxcrasher/Balanced(.701, 숙련 보유+박투박 기능 부합)이며 dlp가 아님. left-release-A 프리셋의 LDM dlp 공급 요건은 고메스 기능으로 충족 불가 — 진성 DLP형(사라·베르그발) 영입 또는 boxcrasher 절충 필요.\u000a\u000a[2026-07-31 H안] 프리셋 LDM 선발로 승격되며 처방을 dm_holding/Ball-Winning → **dm_dlp/Roaming .789**(숙련✓)로 교체. 커널 교체로 만잠비(.726)와 순위가 역전됐다(이전 만잠비 .812 > 고메스 .797). ⚠️ 캐비앗: 고메스도 기능상 볼위너이고(창조 kp .3·xA .04) 스쿼드에 진성 DLP가 없다 — 적합을 위해 기능 정합을 포기한 칸이다. [2026-08-05 역할 처방 확정 — 기존 dm_dlp/Roaming 유지] LDM(x=38) 전수 채점: dm_dlp/Roaming 0.789 → dm_dlp/Build-Up 0.714(Δ.075) → dm_boxcrasher/Balanced 0.685 → dm_holding/Roaming 0.669(Δ.120) → dm_dlp/Defend 0.578 → … → dm_holding/Ball-Winning 0.452(9/10). RDM에서는 0.680으로 LDM보다 Δ.109 낮아 **좌측 배치 확정**. [기능축 충돌은 계승 — 명시적 지불] 툴 FUNC_AXIS가 고메스를 {role:dm_holding, mode:prefer}로 두고 why에 "창조 전무(kp .3 · xA .04)로 기능축은 볼위너. 다만 dm_dlp 적합이 뚜렷이 높아 프리셋은 dlp를 채택 — 적합을 위해 기능 정합을 포기한 칸"이라 적어뒀다. 2026-08-05 이벤트 측정이 그 근거를 **독립 재현**했다: 키패스 0.30/90(FUNC_AXIS의 kp .3과 정확히 일치). dm_holding/Roaming으로 돌리면 .789→.669로 Δ.120 손실이고 동점 임계(.03)의 4배라 타이브레이커 논리로 정당화되지 않는다 → dm_dlp/Roaming 유지. [카마라와의 3선 분담] 겹침 .715로 가용 피봇 조합 중 최저(고메스↔오나나 .874가 최고 중복, 카마라↔오나나 .814, 카마라↔바클리 .806, 고메스↔바클리 .753). 좌우는 열중심 고메스 46.8 vs 카마라 62.3, 깊이는 수비3rd 고메스 7% vs 카마라 11~15%. **기능 분담은 역할 이름이 아니라 슬롯+선수 능력치가 만든다** — 이벤트 per-90: 고메스 태클 3.52 vs 카마라 2.33 / 카마라 패스 52.5 vs 42.5 · 키패스 0.93 vs 0.30 · 인터셉트 1.40 vs 0.70 · 롱볼 정확도 62.5% vs 44.0%. 즉 카마라 배급·읽기, 고메스 압박·차단. ⚠️ 표본 교란: 카마라는 25-11~26-01 빌라(4위권), 고메스는 26-02~05 울브스 — 약팀 미드필더는 구조적으로 패스가 적고 태클이 많아 교란 방향이 관측과 일치한다. 비율 지표(롱볼 정확도 18.5pp 차·키패스 3.1배)가 더 신뢰된다. ⚠️ 불변규칙 7 — 이 실측은 울브스 체제 표본이므로 개인 위치 성향 기준선으로만 쓰고 에메리 3선 구조의 근거로 쓰지 않는다. 빌라 소속 공식전 표본은 0경기다(프리시즌 5경기는 SofaScore 선수별 데이터 전건 404).'),'SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 39경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(121,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg → Aston Villa','CM/AM','CAM','CONFIRMED',NULL,'35345X9578542261322300020',46.46999999999999887,61.39000000000000056,12,7.200000000000000177,'cam_halfwinger','Balanced','cam_halfwinger','Balanced',0.8609999999999999876,'합류확정 멀티포지션 부여: 스위스 대표팀 전진 배치 실측 — 월드컵 2경기(캐나다 8.1·알제리 7.8)+친선 2경기(호주·요르단, lineup pos=F) 통합 4경기 168pt, 중심 tool(46.5,61.4). CAM 배치 cam_halfwinger/Balanced 0.817 — 클럽(프라이부르크) 딥롤 그리드의 CAM 적합(0.575)과 달리 대표팀 전진 표본에서 10번 적합 뚜렷. 월드컵 3골(8강 진출)이 이 전진 롤에서 나옴 — 클럽 box-to-box와 별개로 세컨드 스트라이커/10번 활용 여지 실증.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured:national','실측 HIGH — 25/26 전수 12경기. 스위스 대표팀 12경기 통합 — 전진 배치 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(122,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg → Aston Villa','CM/AM','LM','CONFIRMED',NULL,'35345X9578542261322300020',46.46999999999999887,61.39000000000000056,12,7.200000000000000177,'wm_insidefwd','Balanced','wm_wideplm','Attack',0.6520000000000000239,'합류확정 멀티포지션 부여: LM 순수 출전 표본 없음 — 대표팀 전진 그리드(4경기 168pt)의 LM 슬롯 재배치 적합 0.700(wm_insidefwd/Balanced), 클럽 그리드 기준은 0.607. 좌 하프스페이스 커버는 가능하나 터치라인 고정형이 아닌 중앙 회귀 성향 — 로테이션/변형 옵션 등급.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured:national','실측 HIGH — 25/26 전수 12경기. 스위스 대표팀 12경기 통합 — 전진 배치 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(123,'AVL','2026-summer','Nicolas Jackson',NULL,'잭슨',76,NULL,'Chelsea','ST','ST','MEDIUM-HIGH (⬇ HIGH에서 하향 — ATM 우위)','2026-08-20','357324X673345312211100000',45.02000000000000313,67.1700000000000017,28,6.919999999999999929,'st_false9','Attack','st_false9','Attack',0.723999999999999977,'[2026-08-21 하향] §2-1 등급 보정 「경쟁 클럽이 협상 단계에서 앞섬 → 한 단계 하향」 적용. ⭐⭐ 아틀레티코 마드리드 축이 빌라를 추월했다 — SD **Mateu Alemany가 08-19 말라가전 관전 후 08-20 오전 런던행**, 첼시 이사회와 **대면 회동(08-20~21)**. 구조는 **임대 + 첼시 급여 일부 분담 + 비의무 매수옵션**이고 COPE(Antonio Ruiz) 08-20 20:08은 「cerca de cerrar la cesión」, Marca(Carlos Fernández)는 「주말 전 임대 공식화 목표」로 적는다. ATM 발의는 **시메오네의 명시적 요청**이고 트리거는 **쇠르로트 근육 부상 확정 + 알바레스 부진**이다. ⭐ 선수 측 선호가 ATM으로 기울어 있다 — **스페인 복귀 희망**(비야레알 유스·미란데스 임대 이력), 「로히블랑코 유니폼을 원한다」. ⛔ **빌라 축 진전은 26일째 0이다**(07-28 이후 단계 전진 없음). Romano가 명시한 선행 조건 「왓킨스를 알힐랄에 팔면」은 미충족이고 왓킨스 건은 €45m 거절 + 벤제마 급여 병목으로 정지해 있다. [구조] 빌라는 **사실상 완전이적만 가능**해서 첼시가 ATM과 협상 중인 **임대** 구조와 어긋난다 — ⚠️ 단 **그 제약의 원인은 UEFA 규정이 아니라 첼시의 구조 선호다**(아래 「스왑 연계 규정」 항 참조). 가르나초 임대 보유는 첼시발 추가 임대를 막는 별개 제약이다. [1티어 충돌 미해소] Romano 08-19 「첼시는 완전이적 €45~50m을 겨냥하고 임대를 검토하지 않는다」 ↔ 스페인 2티어 2곳 「임대+급여분담 협상 중」. 첼시 측 1티어 확인 0건이라 ATM 축을 HIGH로 읽지 않았고, 그래서 빌라를 DEAD로 내리지도 않았다. ⇒ **DEAD 전환 트리거 = 1티어가 ATM 임대 합의를 확인**하는 것. | [2026-08-21] ⭐⭐ **45일 규정의 기산점·계산·탈출경로가 확정됐다(원문 문언은 미확정).** **기산점 = 두 구단 간 「첫 이적의 완료(completion)」** — 등록일이 아니다. ⭐ **독립 검산**: 토날리 → 토트넘 **07-06 + 45일 = 08-20**으로 산술이 정확히 맞는다. ⇒ **로저스 07-21~22 + 45일 = 09-04~05로 창 마감(09-01) 안에 만료되지 않는다는 어제의 산술이 확인됐다.** ⭐⭐ **그런데 탈출 경로가 있다** — 「**매입 의무**부 임대」는 조건이 45일 창 안에 정해지면 스왑에 포섭되지만 「**매입 옵션**부 임대」는 포섭되지 않는다. ⇒ 어제의 이지선다(스왑 감수 / 미성사)가 **삼지선다(옵션부 임대로 구조 변경)** 로 바뀐다. ⛔ 다만 그 경로는 규정이 아니라 **첼시가 막고 있다** — 첼시는 완전이적 €45~50m만 원한다. ⇒ **병목의 정체가 「45일 산술」이 아니라 「첼시의 구조 선호」로 재특정된다.** ⭐ Telegraph: 빌라는 **£60m 미만**이어야 가능하고, 첼시는 「**매입 의무 포함**이면 임대도 검토 가능」이라 한다. ‖ **[스왑 연계 규정 — 2026-08-21 정본, 동시 진행 세션 판정 채택]** ⭐ **기산점 = 두 구단 간 「첫 이적의 완료(completion)」이고 등록일이 아니다.** 독립 검산: **토날리 → 토트넘 07-06 + 45일 = 08-20**으로 산술이 정확히 맞는다. ⇒ **로저스 07-21~22 + 45일 = 09-04~05로 창 마감(09-01) 안에 만료되지 않는다**는 산술이 확인됐다. ⭐⭐ **그러나 탈출 경로가 있다** — 「**매입 의무**부 임대」는 조건이 창 안에 정해지면 스왑에 포섭되지만 「**매입 옵션**부 임대」는 포섭되지 않는다. ⇒ 「스왑 감수 / 미성사」 이지선다가 **「옵션부 임대로 구조 변경」을 포함한 삼지선다**로 바뀐다. ⛔ **그런데 그 경로를 막는 것은 규정이 아니라 첼시다** — 첼시는 완전이적 €45~50m만 원한다. ⇒ **병목의 정체가 「45일 산술」이 아니라 「첼시의 구조 선호」로 재특정된다.** Telegraph: 빌라는 **£60m 미만**이어야 가능하고 첼시는 「**매입 의무 포함**이면 임대도 검토 가능」이라 한다.','Fabrizio Romano(1티어) 관심·에메리 각별 신뢰 확인 ; Football Insider(2티어) £60-65m 요구 ; Yahoo Sports "step up talks" ; SofaScore API player 1085381 (2026-07-21) ; thehardtackle(2026-07-19,21) 논의/가격 설정 ; Yahoo Sports(잭슨 open to move) ; teamtalk(2클럽 논의 중) ; Romano X 2079473534951211218 ; teamtalk nicolas-jackson-villa-break-transfer-record (재검증 07-26); Sky Sports; BBC(gossip); TeamTalk; Africasoccer ; [08-05 심층] Ornstein/The Athletic(1티어) 2026-07-22 4년 계약 골격 via https://uk.sports.yahoo.com/news/why-aston-villa-sign-nicolas-180000917.html ; Plettenberg/Sky Germany 2026-07-28 https://www.caughtoffside.com/2026/07/28/aston-villa-nicolas-jackson-transfer-florian-plettenberg/ ; Romano 2026-07-28 임대 불가 확정 https://www.givemesport.com/aston-villa-nicolas-jackson-chelsea-transfer-romano-update/ ; Sky Sports(Sheth) 회의론 영상 2026-07-28 https://www.skysports.com/football/video/12606/13567768/nicolas-jackson-why-aston-villa-may-avoid-signing-striker-from-chelsea ; 웰벡 첼시 이적 2026-08-01 https://www.espn.com/soccer/story/_/id/49478554/danny-welbeck-chelsea-brighton-premier-league-transfers ; BBC 알론소 발언 2026-08-04 ; Daily Mail(Rosser) 2026-08-04 스퍼스 참전 → 당일 football.london 부정 https://www.sportsmole.co.uk/football/spurs/transfer-talk/news/nico-or-nic-no-jackson-to-tottenham-transfer-truth-revealed_602396.html ; BBC Gossip(2026-08-12, 원출처 Telegraph) https://feeds.bbci.co.uk/sport/football/articles/cz0yg9e85pvo ; Sky Sports 2026-08-12 https://www.skysports.com/football/news/11095/13565547/nicolas-jackson-transfer-to-aston-villa-or-tottenham-why-striker-from-chelsea-could-yet-prove-to-be-underrated ; Tribal Football 2026-08-15 https://www.tribalfootball.com/article/soccer-premier-league-nicolas-jackson-wanted-by-aston-villa-but-a-loan-deal-is-impossible-this-summer-7c6cf336-3df8-4d14-b5a9-b0a380f0683a ; Fabrizio Romano(1티어) 임대설 부인 ; RMC Sport(2티어) via GFFN 2026-08-15 19:39 UK ; FootballTransfers(UEFA 45일 규정 해설) https://www.footballtransfers.com/en/transfer-news/uk-premier-league/2026/07/chelsea-transfer-news-alejandro-garnacho-morgan-rogers-aston-villa-uefa ; Sky Sports News/James Savundra(1티어) 2026-08-13 08:22 UK (UEFA 스왑 규정 명시) https://www.skysports.com/football/news/11668/13572382/chelsea-transfer-news-enzo-fernandez-nicolas-jackson-malo-gusto-and-more-in-spotlight-as-blues-look-to-player-sales ; BBC Sport(1티어) 2026-08-15 (알론소 결정으로 명단 제외) ; RMC(2티어) 2026-08-16 (토트넘 철수) ; Sky 13572382 (08-13 08:22 UK) — £65m 호가 + UEFA 스왑·settlement 제약 원문','호가 스펙트럼 넓어 단일값 미채택: €45~50m(Romano) / £65m(Sky 13572382, 08-13) / €69~70m / ETV €40m. ⚠️ ATM 축 근거는 스페인 2티어(Marca 계열·COPE)이고 1티어는 Moretto·Romano 공동 유튜브 인용(원 영상 타임스탬프 미확정). ⚠️ BBC 「Chelsea agree to let striker Jackson leave club」은 URL 404로 발행일 확인 실패 — 등급 근거 미사용. ⚠️ 불변규칙 7: ATM 근거는 아틀레티코 축의 스페인 매체 취재다. 빌라 축 실측·단계와 섞지 말 것. | [2026-08-21] 정체 **27일째**. ⚠️ **동시 진행 세션은 이 행을 「HIGH(정체) 유지」로 적었으나 채택하지 않았다** — 같은 세션이 CHE 유출 행에 「아틀레티코가 최선두다」를 쓰면서 빌라를 HIGH로 남긴 것은 **내부 모순**이다. §2-1(경쟁 클럽이 협상 단계에서 앞섬 → 한 단계 하향)을 적용해 **MEDIUM-HIGH를 유지**한다. ATM 행도 MEDIUM-HIGH이므로 두 축이 대등하게 표시되고, 「ATM 최선두」는 rationale의 단계 서술로 표현된다. ⛔⛔ **「45일」을 정본으로 기재하지 않는다** — UEFA 공식 문서(2025년판 부속서 G.4)에 **그 수치가 없다**. 공식 기준은 ⑴ 동일·연결된 이적 계약 ⑵ 상계 가능한 동등·유사 지급 의무이고 참조 회계기준은 **IAS 38 ¶45~47**이라 **검색이 「45」를 문단번호와 혼동하는 경로가 실재한다**. 2026-07 개정 언급이 있어 신규 조항일 가능성이 높다 ⇒ **준확정으로 두고 등급 판단에만 쓴다.** ‖ **[스왑 연계 규정 — 수치 취급 · 2026-08-21 동시 세션 판정 채택]** ⛔⛔ **「45일」을 정본 수치로 기재하지 않는다** — UEFA 공식 문서(2025년판 부속서 G.4)에 **그 수치가 없다.** 공식 기준은 ⑴ **동일·연결된 이적 계약** ⑵ **상계 가능한 동등·유사 지급 의무**이고, 참조 회계기준이 **IAS 38 ¶45~47**이라 **검색이 「45」를 문단번호와 혼동하는 경로가 실재한다.** 2026-07 개정 언급이 있어 신규 조항일 가능성이 높다. ⇒ **준확정으로 두고 등급 판단에만 쓴다.** ⚠️ 내가 08-21 09시 회차에 적은 「45일은 금액 상한 규정으로 확인됐다」·「van Hecke/Vuskovic로 보아 45일은 식별 테스트다」는 **원문 근거가 없는 과잉 확정이었다 — 철회한다.** 결론(창 안에 만료되지 않는다)은 같지만 근거의 강도가 다르다.');
INSERT INTO transfer_targets VALUES(129,'AVL','2026-summer','Alejandro Garnacho',NULL,'가르나초',58,NULL,'Chelsea','LW','LM','CONFIRMED',NULL,'77111X4111510006100010100',22.30000000000000071,66.5,38,6.990000000000000213,'wm_winger','Attack','wm_winger','Attack',0.7710000000000000186,unistr('첼시 초기 로그론 + 의무구매옵션(사실상 확정), 4년 계약. Romano "here we go" + Ornstein 메디컬 완료 확인 (2026-07-22/23). [2026-07-28 FC26 통합 확인] 실측 0.911 + 숙련 wm_insidefwd+ 일치 + PAC86/감아차기 — 처방 확정.\u000a\u000a[2026-07-31 obs#94 커널 교체 + H안 재설계] 처방을 wm_insidefwd/Attack → **wm_winger/Attack .804**(숙련✓)로 교체. 옛 placedMap이 인사이드 포워드 커널을 터치라인(x=14)으로 시프트해 적합을 .911로 부풀리고 있었고, EA 정본 변형으로는 .671이다. 실측에 맞는 것은 winger 계열이며 좌측 해방의 성격이 컷인 → 터치라인 침투로 바뀐다. 뱅크는 0.00 유지라 C1(두 줄 4) 무사.'),'SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 38경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(135,'AVL','2026-summer','Emerson Royal','에메르송 호이알','에메르송',NULL,856123,'Flamengo','RB','RB','DEAD (STALE — 최신 보도 2026-07-28 이후 2주+ 무소식)','2026-07-28','000250002X000150002600012',86.20000000000000284,56.70000000000000284,6,6.879999999999999894,'fb_att_wb','Support','fb_att_wb','Support',0.949999999999999956,'Matty Cash 백업 필요(안드레스 가르시아 게타페 임대行) — Villa가 Flamengo에 €9m 공식 제안 제출(6/23), Flamengo 거부 후에도 재제안 검토 중. Sky Sports Paper Talk(출처: The Athletic)가 협상 사실 보도, 선수 본인도 공개적으로 제안 수령 확인. 아직 합의 단계 아님(Flamengo 계약 2028까지, 판매 거부 기조) → MEDIUM-HIGH(1티어 협상 보도, 합의 전). [2026-07-29 14시 재확인 — 유지] 디테일 진전: 블록 주체=자르딤 감독(ESPN Brazil Andrade — "회장단은 승인 의향, 감독이 중단"). €9m→€10m 증액 제안도 보류됨. 선수는 공개적으로 긍정 반응, 협상 재개 여지 유효. [2026-07-30 실측 완료] 툴중심(86.2,56.7)=우측 전용. RB 커널 적합 fb_att_wb/Support 0.950 > fb_inverted/Attack 0.923 — 캐시 실측의 동일역할 적합(0.898)을 상회. 전방2행/자기진영2행 질량비 0.53/0.31 vs 캐시 0.33/0.47 → 캐시보다 뚜렷한 전진형 풀백(공격 관여 +0.20, 수비 커버 -0.16). 함의: C(우측 침투) 프리셋의 RB 처방 fb_att_wb/Support에 캐시보다 정합적이나, 자기진영 질량 하락이 이미 라인 48로 내린 C의 수비 리스크를 더한다 — 프리셋 채택은 별도 판단. [경쟁구도 2026-07-30] 빌라 단독 우위(경쟁 클럽 0건) — 오퍼를 낸 유일한 클럽이고 선수도 공개 호응("이 제안을 받아 매우 기쁘다"). 장애물은 경쟁이 아니라 플라멩구의 스쿼드 판단: Casagrande(플라멩구 전담) — 지금 팔면 자르딤이 바렐라의 즉시 대체자를 잃는다는 이유이며 금전 문제가 아니다(빌라는 이미 호가 충족, 결렬이 아니라 냉각). 상향 트리거 = 플라멩구의 우측 백업 확보(에스투피냔-밀란 블록과 동일 패턴). [2026-08-09 재확인 — MEDIUM-HIGH 유지, 신규 근거 0건] 오늘 검색에서도 최신 보도가 6월말~7월 수준(플라멩구가 스쿼드 뎁스 우려로 €10m 오퍼 거부, 매각 자체를 보류)에 머물러 있다. 선수 본인은 "제안을 받아 기쁘다, 미래는 모른다"로 문을 열어둔 상태 유지. ⚠️ **last_news_date 2026-07-28 기준 STALE 시한(14일)은 2026-08-11** — 08-09 현재 12일 경과, 2일 남았다. 다음 회차(21시)~08-11에 신규 보도가 없으면 §4-3에 따라 DEAD(STALE) 전환 대상이다. 재확인 날짜를 last_news_date로 쓰지 않는다(§4-3 함정 규칙). [2026-08-10 심야 — STALE 전환 근거 확정] 전용 검색 2회로 **08-01 이후 빌라 링크 신규 보도가 0건**임을 확인했다(오늘 검색에 걸린 전건이 6월말~7월 빈티지의 재순환). 확인된 최신 실보도 타임라인: 2026-06-23 €9m 오퍼(ESPN Brasil) → €10m 인상(Venê Casagrande) → **플라멩구가 RB 뎁스 우려로 매각 철회**(재정 사유 아님 명시 — Varela와의 경쟁 필요) → 7월말 Bruno Lemos "빌라는 플라멩구의 대체자 확보를 기다리는 중". 선수 본인 발언(Itatiaia Esporte)도 7월 것이다. 계약 2028 + 1년 옵션. ⇒ `last_news_date` 2026-07-28 기준 오늘 **13일**. **08-11 시한 도달 시 §4-3 전환 근거가 성립한다**(신규 근거 0건 확인 완료). ⛔[2026-08-10 STALE 전환 집행] §4-3에 따라 `DEAD (STALE)`로 전환한다. **실질 근거**: 스캔 에이전트가 전용 검색 2회로 **08-01 이후 빌라 링크 신규 보도 0건**을 확인했고(검색에 걸린 전건이 6월말~7월 빈티지의 재순환), 최신 실보도는 7월말 Bruno Lemos "빌라는 플라멩구의 대체자 확보를 기다리는 중"에서 멈춰 있다. ⚠️ **절차 명기**: 전환일 기준 경과는 **13일**로 §4-3의 "14일 초과"에 하루 못 미치며(14일 시점 = 2026-08-11), **사용자 판단으로 하루 앞당겨 집행**했다. 실질 요건(신규 근거 0건)은 충족돼 있다. ⚠️ **삭제하지 않는다** — 이 행은 `fit_sim` **0.95**(현 후보 최고값)와 `map25` 실측을 보유하며, §4-3이 정체 건을 지우지 않는 이유가 정확히 그 상실 방지다. DEAD만으로 `injectTransferCandidates()`가 `/^DEAD/i`를 필터해 툴·SQUAD_SLOTS·XI_POOL에서 사라진다. **복원 조건**: 빌라 링크 신규 보도 확인 시 §2 등급표로 재판정해 `likelihood` 되돌리고 `last_news_date` 갱신, `rationale`에 `[STALE 해제 YYYY-MM-DD]` 기록.','Sky Sports(via The Athletic) 2026-07; Yahoo Sports/Sports Mole 2026-07','실측 6경기(45분+·히트포인트 62~107): FLA-SPA 90''7.1 / CHA-FLA 90''6.7 / FLA-COR 90''7.1 / FLA-CUS 90''7.1(리베르타도레스) / FLA-ELP 90''6.7(리베르타도레스) / VIT-FLA 90''6.6(코파) — 2026-05-15~07-26, 평균 6.88. 캐비앗: ① 브라질 리그·남미 대회 표본(리그 강도 보정 없음, 시세 LASK 사례와 동일 한계) ② 프리시즌 친선 4경기는 표본 제외 ③ INT-FLA(26'')·CAP-FLA(8'')·GRE-FLA(25'')은 45분 미달로 제외. 측정: claude-in-chrome, SofaScore API event/{eid}/player/{pid}/heatmap.');
INSERT INTO transfer_targets VALUES(139,'AVL','2026-summer','Allan','아우안','아우안',77,1835889,'Palmeiras','RW/CAM','RM','MEDIUM-HIGH','2026-08-09','012350125X111370012700013',77.14000000000000056,56.8299999999999983,42,7.089999999999999858,'wm_winger','Balanced','wm_winger','Balanced',0.8139999999999999458,'로저스(첼시 £117m) 대체 창조 자원. 빌라가 €25m+옵션 €5m(총 €30m)·5년(+1년 옵션) 공식 입찰 → 팔메이라스 거절. SD Anderson Barros가 대리인에게 "협상 의사 없음" 직접 통보, 요구선 €45m 초과(나폴리 €35m·뉴캐슬·제니트 기거절). 계약 2029로 셀링클럽이 협상력 우위. [경쟁구도 2026-08-01] 단계는 빌라가 최선두(유일한 실제 입찰) — 뉴캐슬·리버풀은 관심 단계 보도뿐. 판정 **빌라 우위**이나 병목은 경쟁 클럽이 아니라 **셀링클럽 블록**이다. 등급 유지(HIGH는 협상 단계 요건 미충족 — 상대가 협상 자체를 거부). [실측 2026-08-01] SofaScore 히트맵 6경기(45분+·히트포인트 15+, 2026-05-05~07-30, 전부 팔메이라스) 균등가중 그리드. 중심 툴좌표 (77.2, 59.4) = **우측·전진** 편향이 뚜렷하고 평균 평점 **7.18**(최고 8.4). RM 슬롯(x=85) 커널 적합 **wm_winger/Balanced .812** — 기존 RM 후보 하지무사 .821·은디아예 .825와 **동급**이고 둘 다 DEAD인 지금 RM 슬롯의 유일한 실측 보유 후보다. ⚠️ W군(순수 윙어)으로 재면 w_wideplm/Build-Up .870으로 더 높다 = **뱅크(WM) 역할보다 해방 윙어에 가까운 풋프린트**이며, 에메리 우측이 요구하는 4-4-2 복귀(obs#27)와는 그만큼 어긋난다. CAM으로 재면 .674로 급락 → 등재 슬롯은 RM이 맞다. [2026-08-01 처방] opt=fit=wm_winger/Balanced(.812) — 타 영입 후보와 같은 규약(실측 argmax를 처방으로). ⚠️ 현 구조에서 RM은 두 줄 4의 **뱅크 칸**이라(obs#124) 실제 기용 시 wm_widemid/Support **.734**를 지불하게 된다(−.078). 즉 아우안은 해방 사이드용 자원이고, 좌측이 이미 해방으로 우세한 현 스쿼드에서는 구조적으로 어긋난다. [2026-08-02] ESPN Brasil(Bruno Andrade): 빌라는 **포기하지 않았고 2차 입찰을 준비 중**이다 — 다만 **아직 제출 전**이라 단계 변화는 없다(등급 유지). 팔메이라스가 협상 자체를 거부 중이라 이번 창 내 성사는 회의적이고, 브라질 시즌 종료 후 1월 재평가가 현실적이라는 관측이 병기된다. [2026-08-03] 셀링클럽 구조 제약 확인 — 팔메이라스는 Allan 경제권 70%를 보유하고 **국외 이적 바이아웃 €100m(R$630m)** 이 걸려 있다. ⚠️ 이 조항은 빌라 관심에 대한 신설 대응이 아니라 **2024-11 재계약 때부터 존재하던 상수**다(ESPN Brasil, 최초 보도 2025-02-25 — 당시 2027 만료·€100m, 이후 2029로 연장). 즉 €45m+ 요구선과 €100m 조항은 별개 층이며, 협상 결렬 시 빌라가 넘어야 할 실제 천장은 후자다. 추가로 아벨 페레이라가 기자회견에서 "협상이 이뤄진다면 주변부 선수에 한한다"고 직접 발언(1차 출처=공개 회견). ⚠️ **2030까지 재연장+조항 증액 협상 중**이라는 서술은 thefootball.com.br(3티어, 기자 미표기) 단독이라 채택하지 않는다 — ESPN 기사에는 해당 내용이 없다. [2026-08-09 최신화 — MEDIUM-HIGH 유지, 셀링클럽 블록 확인] ⚠️ 소속팀은 팔메이라스다(플라멩구 아님 — 플라멩구의 Allan은 동명이인 Allan Rodrigues, 현재 코린치안스 임대). ESPN(sources 기반): **빌라의 €30m 오퍼를 팔메이라스가 거부**했고 €45m 수준으로의 인상을 요구. 오퍼 구조는 고정 €25m + 보너스 €5m + 5년 계약(+1년 옵션). TeamTalk: 팔메이라스 회장 Leila Pereira와 감독 Abel Ferreira가 매각에 반대하며 "최근 아카데미 최고 재능, 가치가 계속 오를 선수"로 판단 — 빌라의 오퍼에 감사를 표하되 **비매품 통보**. [등급 판단] §2-1 보정표상 이는 "경쟁 클럽 우위"가 아니라 **셀링클럽 기조(잔류·호가)** 사유다. 빌라는 관심이 아니라 **실제 공식 오퍼를 제출한 단계**이고 2차 입찰도 배제되지 않았으므로 MEDIUM-HIGH 유지 — 다만 €15m 갭과 구단 수뇌부의 공개 반대가 병목이다. 선수: 22세, 2026시즌 6골 4도움, 통산 88경기 16공격P. 리버풀·뉴캐슬도 링크. [2026-08-13 정형값 교정] player_matches의 45분+·hit_points>=15 전체 42경기(3166분)를 core.aggregate로 재집계. RM(WM군) 슬롯 제한 argmax는 wm_winger/Balanced .814. 순수 W군 .837은 EA 노이즈 구간 차이(.023)의 참고값이며 실행 슬롯 정형값에는 쓰지 않는다. | [2026-08-20 14시] ⭐ **STALE 08-23 시계는 리셋되지 않는다 — ESPN 고유 ID 시간키로 확정했다.** André Hernan의 「R$174m 상회 신규 오퍼 준비」가 2회차 연속 날짜 없이 재등장했으나, €30m 거절 원문의 ESPN ID가 **49478318**로 08-19 회차가 확정한 기준점 **49597770(08-13) · 49658716(08-19)보다 크게 낮다** ⇒ 이 기사는 **08-13보다 이전**이고 현 last_news_date 08-09와 정합한다. **「신규 보도」가 아니다.** 팔메이라스 문턱 €45m·매각 불가 방침·Abel 공개 발언은 변동 없음.','ESPN(1티어, Adriana Garcia 기명, sources 표기, 2026-07-29) https://www.espn.com/soccer/story/_/id/49478318/aston-villa-premier-leauge-allan-brazilian-serie-30-million-offer-rejected-sources ; 최초 정보 André Hernan(BR) ; TEAMtalk','MEDIUM-HIGH — 1티어가 **실제 제출된 입찰**을 확인(단순 관심 아님). 실측 완료(2026-08-01) — 6경기 균등가중, 인코딩 규약은 맥긴 14023928 회귀 검증(44포인트·25셀 완전 일치)으로 확인. ⚠️ 표본이 전부 **브라질 세리에A**라 리그 수준 보정 없음. ⚠️ 적합 .812는 슬롯 유형 WM 제한 하의 argmax이고, 무제한이면 W군이 더 높다(위 캐비앗). [2026-08-03] €100m 바이아웃은 ESPN Brasil로 교차 확인됨(신설 아님·상수). 2030 재연장설은 미채택(3티어 단독). | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). **41/43 우측 우세**. RW(.837) > RM(.814)이나 Δ.023은 EA 노이즈 구간이라 슬롯은 RM 유지. 표본은 팔메이라스(브라질 세리에A) — **리그 수준 보정 없음**. 45분+ 42경기(3166분) 집계. 종전 6경기 표본 wm_winger/Balanced 0.812 → w_winger/Balanced 0.837. | [2026-08-20 14시] ⭐ 발행일 표기가 아예 없는 기사도 **같은 매체의 확정된 ID 기준점 2개 사이에 끼워 넣어 「이전/이후」를 판정**할 수 있다 — 절대 시각은 못 얻지만 STALE 판정에는 충분하다. ⚠️ 단 이 기법은 그 매체의 ID가 단조 증가할 때만 유효하다(ESPN·Sky·TMW는 확인됨).');
INSERT INTO transfer_targets VALUES(141,'AVL','2026-summer','Matteo Ruggeri','마테오 루헤리','루헤리',NULL,965011,'Atlético Madrid','LB','LB','CONFIRMED','2026-08-19','32100X2000410007200031000',13.59999999999999965,47.20000000000000284,6,6.769999999999999574,'fb_att_wb','Support','fb_att_wb','Support',0.948999999999999955,unistr('[2026-08-11 갱신] Romano(1티어, 08-11 22:41): **개인 조건 합의 완료**, 선수가 버밍엄으로 이동해 **메디컬·계약 서명 진행 가능**. 이적료는 종전 €20m 표기에서 **€25m + 애드온 €1.5m(총 €26.5m)** 로 정정. [경쟁구도] 리버풀·뉴캐슬 관심은 소멸, 빌라 단독 우위. 아틀레티코는 그리말도 영입 후 매각 의사. ⚠️ **CONFIRMED 아님** — 메디컬 완료·구단 공식 발표 0건이고 Romano의 ''here we go''도 아직 없다. 슈퍼컵(08-12) 전 등록은 무산됐다. 다음 회차 CONFIRMED 전환 1순위. [2026-08-13] **메디컬 단계 진입** — Romano(1티어) 08-12 트윗 `2087469710958850427`: "오늘 늦게 잉글랜드로 이동해 빌라 메디컬". 08-11 "here we go" 후속이다. 08-13 현재 **구단 공식 발표 0건**이라 CONFIRMED 전환은 보류 — 다음 회차 1순위 그대로. 이적료 €25m + €1.5m 애드온(총 €26.5m) 불변. [2026-08-14 재확인] AS 2026-08-13 09:12 UTC: 선수가 버밍엄으로 이동해 최종 절차를 진행 중. 구단 공식 발표는 아직 없어 HIGH 유지, CONFIRMED 전환 보류. [2026-08-14 21시 재확인 — HIGH 유지, CONFIRMED 전환 보류] **구단 공식 발표가 여전히 0건**이다. 판별 근거: Sky Sports ''Premier League deals, ins and outs'' 페이지가 **08-14 14:46 UK 갱신 시점에도 빌라 IN 목록에 루헤리를 싣지 않았다**(마잠비·고메스·시세·얼리·가르나초만 등재). Romano 08-14는 "being announced soon", 버밍엄월드는 "48시간 내 메디컬"까지다. 조건은 €25m 고정 + €1.5m 애드온(총 €26.5m), 개인 조건 합의·메디컬 단계로 불변. ⇒ **다음 회차 CONFIRMED 전환 1순위**(전환 시 squad_entries 승격 동반). [2026-08-15 재확인 — HIGH 유지, ⚠️**발표 지연이 만 하루를 넘겼다**] Sky "PL deals, ins and outs" 페이지가 **08-15 13:10 UK 갱신본에서도** 빌라 IN 목록에 루헤리를 싣지 않았다(등재분은 마잠비 £59.5m · 주앙 고메스 £38m · 시세 비공개 · Blade Earley 자유 · 가르나초 임대 5건뿐). 현재 시각 기준 46분 전 갱신본이라 실효 최신이다. 구단 공식 채널(avfc.co.uk)·아틀레티코 채널도 발표 없음 — **등번호·계약 기간 정보가 존재하지 않는다.** 조건 불변(€25m + €1.5m = €26.5m), 단계는 "메디컬 완료·버밍엄 체류·계약 서명 대기". ⇒ 어제 "다음 회차 CONFIRMED 전환 1순위"로 적었으나 **오늘도 전환 근거가 확보되지 않았다**. 단순 행정 대기인지 별건 사유인지 감시 대상으로 격상한다. [2026-08-16 재확인 — HIGH 유지 / ⚠️**발표 지연 4일째**] **Sky ''PL deals, ins and outs'' 08-15 18:44 UK 갱신본**(어제 확인한 13:10보다 5시간 34분 신규)에도 빌라 IN 등재분은 마잠비·주앙 고메스·시세·Earley·가르나초 **5건 그대로이고 루헤리가 없다**. 완비사카도 없다. 타임라인: 메디컬 **08-12(수)** → Romano HWG **08-13** → 현재 **08-16 02:56 BST까지 발표 0** = 메디컬 기준 **만 3일 반**이다(어제 ''만 하루''로 적은 것을 정정한다). ⚠️ **금액이 3분기로 미해소**다 — Romano €25m+€1.5m ↔ **Schira(2티어) €30m·2031년까지·연봉 €4m** ↔ The Athletic 약 €20m. [2026-08-17 — HIGH 유지 / ⚠️발표 지연 6일째, 1~2티어 신규 0건] 메디컬 08-12 → 발표 없음 = **만 5일**. 스페인어·이탈리아어를 병행 확인했으나 최신이 estoesatleti·eldesmarque **08-12**로 전부 구간 밖이다. 오늘 유일한 신규는 **Tom Collomosse(Daily Mail 빌라 담당) 08-16 밤** 「루헤리가 **24시간 내 스즈키와 함께 서명**할 예정」 — ⚠️ Daily Mail은 우리 티어표 2티어 목록에 없어 **등급 근거로 쓰지 않았다**(전담 기자라는 점만 가산). ⛔ 지연 사유는 오늘도 3티어 추정뿐이다 — myoldmansaid(08-16)의 「잘츠부르크 슈퍼컵 원정 → 곧바로 글라트바흐 친선전 일정 때문」은 본문이 스스로 ''potentially''로 헤지한다. 어제의 insidefutbol「신원 배경 조사」와 함께 **둘 다 미채택**.\u000a⚠️ **[2026-08-18 — HIGH 유지 / 공식 발표 지연 7일째]** 1티어 최신이 **여전히 08-12**다. 오늘의 지연 설명은 3티어뿐이다(「빌라가 잘츠부르크 슈퍼컵 → 묀헨글라트바흐 친선으로 직행해 발표가 밀렸고 이번 주 초 확인 예상」).\u000a⚠️ **[2026-08-19 — HIGH 유지 / 발표 지연 8일째]** 1티어 최신이 **여전히 08-12**다. Romano 메디컬 트윗 `2087469710958850427` 스노플레이크 **08-12 09:22:17 UTC** 재확인(오늘 것이 아니다). 지연 사유 보도는 3티어뿐이다. **메디컬 후 8일 미발표는 이례적이며 구조·서류 이슈 가능성을 배제할 수 없다** — 경보 유지.\u000a⭐⭐ **[2026-08-19 21시 — HIGH → CONFIRMED]** **빌라 공식 발표 확인**: avfc.co.uk `/news/2026/august/19/signing-matteo-ruggeri-signing-confirmed/`\u000a(메인 세션 브라우저 직접 확인, 발표 시각 ≈2026-08-19 11:30 UTC). 본문 「Aston Villa is delighted to announce the signing of\u000aMatteo Ruggeri from Atlético Madrid … has completed a **permanent transfer** to B6」 — **완전이적 확정**(임대 아님).\u000a⇒ **메디컬(08-12) 후 8일 미발표라는 "이례성 경보"는 결국 단순 행정·일정 지연이었다** — 구조·서류 이슈는 발생하지 않았다.\u000a⚠️ **구단은 이적료·계약 기간·등번호를 공표하지 않았다** — 따라서 금액 3분기 충돌(Romano €25m+€1.5m ↔ Schira €30m/2031 ↔ Athletic ~€20m)은\u000a**공식으로 해소되지 않았고 단일값을 채택하지 않는다.** [경쟁구도] 종결 — 경쟁 클럽 없음.'),'Marca(스페인 전국지, 원출처) via Matteo Moretto(준1티어) ; https://www.sportsmole.co.uk/football/aston-villa/transfer-talk/news/emery-wants-to-sign-italian-defender-immediately-as-aston-villa-bid-to-resolve-clear-issue_602381.html ; http://insidefutbol.com/2026/08/04/aston-villa-push-for-defender-as-he-weighs-his-options/722198/ ; https://www.eurosport.es/futbol/mercado-de-fichajes-2026/2026/aston-villa-interes-matteo-ruggeri-atletico-de-madrid_sto23325237/story.shtml ; https://uk.sports.yahoo.com/news/aston-villa-could-seal-immediate-101500950.html ; SofaScore /api/v1/player/965011/events/last/0 + /event/{eid}/player/965011/heatmap|statistics ; The Athletic(Jacob Tanswell, 1티어, 2026-08-04, paywall 미열람 — 인용 3매체 발행시각 일치로 확정) ; Marca(Isaac Suarez) 2026-08-04 via Sport Witness ; https://www.givemesport.com/aston-villa-identify-mattero-ruggeri-digne-replacement-transfer/ (2026-08-04) ; Tinti 발언 https://www.romaforever.it/2026/07/21/ruggeri-si-allontana-lagente-tinti-fa-chiarezza-sul-suo-futuro/ (2026-07-21) ; Total Football Analysis 스카우트리포트 2025-07-24(⚠️아탈란타 24/25 데이터) | https://www.marca.com (2026-08-05, via readastonvilla.com/2026/08/05/aston-villa-agree-20m-matteo-ruggeri-deal-as-final-hurdle-remains/) | https://insidefutbol.com/2026/08/05/aston-villa-move-blocked-for-now-as-definitive-yes-is-missing/ (Moretto) ; Romano via football-italia.net/done-ruggeri-agrees-personal-terms-aston-villa/ (2026-08-11) ; AS 2026-08-13 https://as.com/futbol/ruggeri-otro-mas-de-la-maldicion-italiana-del-atletico-f202608-n/ ; Sky Sports PL ins&outs(2026-08-14 14:46 UK 갱신) https://www.skysports.com/football/news/11095/13546618/transfer-news-summer-transfer-window-2026-premier-league-deals-ins-and-outs ; Fabrizio Romano(1티어) 2026-08-14 ; Birmingham World 2026-08-14 https://www.birminghamworld.uk/sport/aston-villa-close-in-on-defender-signing-with-medical-due-8920412 ; Sky Sports PL ins&outs 2026-08-15 13:10 UK https://www.skysports.com/football/news/11095/13546618/transfer-news-summer-transfer-window-2026-premier-league-deals-ins-and-outs ; Football Italia(메디컬·개인조건) 2026-08-13 ; Sky Sports PL ins&outs 2026-08-15 18:44 UK 갱신본 ; Nicolò Schira(2티어) 2026-08-12 ; Fabrizio Romano HWG 2026-08-13 ; ⭐ **Aston Villa 공식(1티어·구단 채널) 2026-08-19** https://www.avfc.co.uk/news/2026/august/19/signing-matteo-ruggeri-signing-confirmed/',unistr('MEDIUM-HIGH — 2티어(Marca, 원출처 직접 보도) + 준1티어(Moretto)가 오퍼 제출 단계를 보도. 1티어(Romano/Sky/BBC/Athletic) 직접 확인은 검색에서 미발견이라 HIGH 미충족. §2-0 발행일 검증 통과: 발행일 2026-08-04 확정, 나이 표기 24세가 실제(2002-07-11생 → 24세)와 일치, 병기 정황(그리말도 아틀레티코 입단·그리스만 올랜도 자유이적·랑글레 벤피카 임대·디뉴 PSG)도 현재 상태와 부합 → 1년 오차 함정 아님. 캐비앗: ⑴ 선수 결정 대기 상태로 무산 가능성 상존, ⑵ 2주 전 대리인 Tinti의 ''아틀레티코 잔류가 계획'' 발언(Sky Sport Italia)과 상충 — 오늘 보도가 더 최신이라 채택하되 상충 사실 명기, ⑶ 실측 표본이 25/26 시즌 종료분이라 아틀레티코 1년차 역할 기준(그리말도 영입 전). [2026-08-05 심층 추가 캐비앗] ⑷ 이적료 보도 충돌 — Cerchione €18m+€3m(최대 €21m, 구조 제시) vs The Athletic ~€25m(총액, 티어 우위). 어느 쪽도 다른 1티어가 복제하지 않았다. ⑸ 선수 측 의사 충돌 — 대리인 Tinti의 2026-07-21 Sky Sport Italia 발언 "아틀레티코에 남는다, 시장에 나와 있지 않다"가 08-03~04 훈련 제외·대리인 마드리드 방문과 정면 충돌. 협상 포지셔닝이었을 가능성이 높으나 선수 본인의 이탈리아 복귀 선호의 흔적일 가능성도 배제 못 함 — 확정 근거 없음. ⑹ 인용 함정 2건 명기: (a) Total Football Analysis 스카우트 리포트는 제목이 "Atletico Madrid 2025/2026"이나 실제 발행 2025-07-24·데이터는 아탈란타 24/25 기반이다 — 25/26 아틀레티코 평가로 인용 금지. (b) BirminghamWorld "Fabrizio Romano confirms £17m deal"은 2025-06 아탈란타→아틀레티코 이적 건으로, 빌라 딜의 1티어 근거로 오인하기 쉬운 재순환 기사다. ⑺ 08-04 기록의 발행일 교차검증 항목 중 "그리스만 올랜도 자유이적"은 2026-08-05 재확인에서 검증 실패(그리즈만은 여전히 아틀레티코 스쿼드에 포함) — 나머지 3개 병기 정황(그리말도 입단·랑글레 벤피카·디뉴 PSG)은 유효하므로 발행일 판정 자체는 유지하되 이 항목은 근거에서 제외한다. ⑻ 실측 한계: @dom/@tight 및 국면(possH/possL) 분리 표본이 없어 에메리의 "풀백은 한 명씩만 전진" 모듈레이션 수행 가능 여부는 판정 불가(디뉴·마첸은 해당 행 보유). ⑼ 부상 이력 — 2021-09~2023-04 근육 부상 클러스터(최장 4개월) 이후 2024년부터 안정화, 25/26 아틀레티코 시즌 부상 기록 없음. 내구성 리스크 LOW-MEDIUM. ⑽ 신체·산출 맥락: 187cm 왼발, 공중볼 승률 92.1퍼센타일(24/25 5대리그 LWB 대비) — The Athletic이 말한 "physical profile"의 정량 근거. 25/26 라리가 26경기(20선발) 1,775분 0골 3도움, 크로스 95회(4.8회/90), 태클 1.88·인터셉트 1.01·클리어 3.19/90. 세리에A 30경기 3도움 → 라리가 26경기 3도움으로 3백 윙백→4백 풀백 전환에도 분당 생산성 유지. | 2026-08-06: 합의 보도는 2티어 복수(Marca·Uria·Moretto) 일치, 1티어 직접 확인은 The Athletic 관심 보도까지. Romano "here we go" 미발행 — CONFIRMED 아님. Mundo Deportivo 원문 발행일 미확정이라 last_news_date는 확인된 08-05로 기록. | [실측 전수 완료 2026-08-12] 2026-08-12 전수 실측(SofaScore 25/26). 종전 6경기 표본을 대체하지 않고 추가한다(불변규칙 2). ⚠️ 표본은 **이전/현 소속 클럽**의 것이고 우리 팀 전술이 아니다(obs#157·#158). **45/45 전 경기 좌측 우세**(좌2컬럼 0.98·우2 0.00)라 좌우 혼입 없음. 표본은 아틀레티코 마드리드. 45분+ 45경기(3612분) 집계. 종전 6경기 표본 fb_att_wb/Support 0.949 → fb_att_wb/Support 0.931. ⚠️ 원소속은 **아틀레티코 마드리드**다(아탈란타 아님 — 2025년 여름 €17m+€3m로 이적). 검색 결과에 아탈란타 표기가 섞여 나오므로 셀링클럽 혼동 주의. ⚠️ 다수 기사에 **"약 한 달 전 제기된 혐의(allegations)"** 가 반복 병기된다 — 발표 지연의 사유일 가능성이 있으나 1~2티어가 인과를 명시한 사례는 없어 **추정이며 근거로 쓰지 않는다**. ⚠️ ''약 한 달 전 제기된 혐의(allegations)'' 병기는 오늘도 반복되나 **1~2티어가 지연과의 인과를 명시한 사례는 여전히 0건**이라 추정으로 쓰지 않는다. ⛔ **오늘의 최대 함정**: dosisfutbolera(→Yahoo Noticias ES, 2026-08-12 12:15 UTC)가 헤드라인에 **"Oficial"**을 달았으나 본문은 Schira 인용이고 스스로 ''메디컬 통과가 남았다''고 적는다 — **가짜 확정 라벨 + 4일 과거**의 이중 함정이다. ⚠️ **[2026-08-17]** 금액 3분기 유지(Romano €25m+€1.5m=€26.5m ↔ Schira €30m·2031년 ↔ The Athletic 약 €20m). ⛔ **avfc.co.uk 공식 발표 0건**을 오늘 메인 세션이 직접 확인했다(뉴스 40건). ⚠️ 스즈키와 달리 **메디컬 이후 1티어 후속이 전혀 없다** — 스즈키는 오늘 Romano가 메디컬 진행을 실시간으로 적었는데 루헤리는 08-12 이후 1티어 침묵이다. 같은 ''메디컬 완료'' 상태로 취급하기 어렵다.\u000a⭐ **[2026-08-18 스노플레이크 검증]** Romano의 「Ruggeri flies to England for medical」 트윗(status **2087469710958850427**)을 ID 역산하면 **2026-08-12 약 09:20 UTC**다 — **''오늘 메디컬''이 아니라 6일 전**이다. 검색·애그리게이터에서 이 트윗이 최신처럼 재노출되는 것을 등급 근거로 쓰면 안 된다(§2-0 보조 지표). ⚠️ 금액은 **1티어 내부에서도 갈린다** — Romano €20m ↔ €25m+€1.5m ↔ Schira €30m(2031·연 €4m) ↔ €18m+€6m. **단일 금액을 채택하지 않는다.** ⛔ 메디컬 후 발표까지 7일은 이례적이라 **구조·서류 이슈 가능성**을 배제할 수 없다.\u000a⭐ **[2026-08-19 21시 CONFIRMED 근거]** 구단 공식 채널 발표로 §2 최상위 근거를 충족했다 — 기자 티어 판정이 더는 필요하지 않다.\u000a⚠️ 잔여 미확정: **이적료·계약 연수·등번호 전부 미공표**다. 08-16 이후 기록한 금액 3분기 충돌은 그대로 미해소 상태로 남긴다.\u000a⚠️ `squad_entries` 행(id=60, FB, `루헤리(합류확정)`)은 **이 발표 이전에 이미 CONFIRMED로 생성돼 있었다** — 이번 갱신으로\u000atransfer_targets와 정합이 맞춰졌다(종전에는 targets=HIGH ↔ squad_entries=CONFIRMED로 어긋나 있었다).\u000a⚠️ 실측 표본은 **아틀레티코 마드리드 45경기**이고 빌라 공식전 0경기다 — 불변규칙 7(팀 축 혼입 금지) 유효.\u000a⭐ **[2026-08-19 22시 등번호 확정]** **No.13** — avfc.co.uk `/news/2026/august/19/signing-ruggeri-squad-number-confirmed/`. 아틀레티코 No.3 · 아탈란타 No.22였다. ⇒ 21시 회차가 「이적료·계약 연수·등번호 전부 미공표」로 남긴 결손 중 **등번호가 해소**됐다. ⚠️ **이적료·계약 연수는 여전히 미공표**이고 금액 3분기 충돌(€26.5m ↔ €30m/2031 ↔ ~€20m)도 미해소다.'));
INSERT INTO transfer_targets VALUES(142,'AVL','2026-summer','Endrick','엔드릭','엔드릭',NULL,NULL,'Real Madrid','RW/ST','RM','DEAD (레알 잔류 결정 — 2026-08-10 Romano/The Athletic)','2026-08-10','013440137X001350112200000',NULL,NULL,20,7.0,'wm_wideplm','Attack','wm_wideplm','Attack',0.8469999999999999752,'[2026-08-12 정정] **08-11 MEDIUM-HIGH 등재는 오류였다.** 근거로 삼은 Romano 발언("관심 있는 두 클럽 — 로마와 아스톤 빌라")보다 **같은 날 나온 더 늦은 Romano 보도**가 결론이었다: 레알이 엔드릭과 그의 에이전트(Roc Nation 포함)에게 **잔류 결정을 통보**했고 무리뉴가 임대 협상을 전면 중단시켰으며 페레스도 동의했다(The Athletic Mario Cortegana 08-10 병행 보도). ⭐ **1월에 재논의하기로 한 것이 확인된다** — 겨울 창 재개 가능 건이므로 완전 종결이 아니다. [경쟁구도] 로마·맨유도 함께 무산. 실측(obs#135, 리옹 임대 20경기 우2컬럼 77.1%)과 커널 적합(RW .907 / RM wm_wideplm/Attack .847)은 보존한다 — 겨울 재개 시 재측정 불필요. | [2026-08-20 14시] ⭐⭐ **Fotmob의 「Aug 14 / AS」 리드를 종결한다 — DEAD 유지, 복원 근거 없음.** as.com이 우리 접근에 하드 차단(400)이라 원문 직접 확인은 **원천 불가**이므로, AS 귀속 콘텐츠를 릴레이로 전수 추적했다. 결과는 **08-07~08-10에 밀집**한다 — 08-07 defensacentral(빌라 미언급) · 08-09 foxdeportes(AS: 「제안 수령 중」) · 08-10 record.mx 05:38 + football365 11:30(AS: 로마·빌라가 「조건 충족」) · 08-10 onefootball 43258216(L''Équipe: 잔류 전망, 무리뉴가 잔류 요청). ⇒ **AS 원문은 우리 DEAD 근거(08-10 Romano/The Athletic)와 동시점 또는 그 이전**이고 **「Aug 14」는 무보강**이다. 08-11 「재고 중」(onefootball 43262720)은 원출처가 Superlider(멕시코 3티어)인 AS 08-10 내용의 재유통이다. 보강 정황: 무리뉴가 차단 · 이사회가 €80m+ 투자 근거로 잔류 지지 · 라리가 개막 전 1군 등록 예정. ⭐ **복원 트리거는 2027년 1월 겨울 임대**로 스페인어 소스 다수가 명시한다.','Fabrizio Romano 발언(2026-08-10) via football365 https://www.football365.com/news/aston-villa-real-madrid-endrick-fabrizio-romano-transfer-update ; AS 원보도 via Managing Madrid https://www.managingmadrid.com/111142/endrick-real-madrid-loan-deal-2026-news ; Fotmob rumours teamIds=10252 (RW Endrick / 어제 / AS) ; 실측 obs#135 SofaScore pid 1174937 ; [정정 근거] Romano 잔류 통보 보도 + The Athletic Mario Cortegana (2026-08-10) via https://www.si.com/soccer/real-madrid-u-turn-endrick-2026-27-season','DEAD — 무산 확정(레알 잔류 결정 통보). ⭐⭐ **이 건은 §2-0 지표 4의 실패 사례로 남긴다**: "같은 매체 안에서도 최신순 정렬을 하라 — 연도가 맞아도 이미 뒤집힌 중간 기사일 수 있다"가 **같은 날 안에서도 성립**한다. 08-11 등재 시 Romano 발언을 인용한 football365 기사를 잡았는데, 동일 08-10에 Romano가 잔류 결정을 별도로 보도했고 그쪽이 결론이었다. 발행일(08-10)이 맞았기 때문에 지표 1~3으로는 잡히지 않았다 — **날짜가 같아도 시각 순서를 봐야 한다.** ⚠️ 행을 삭제하지 않는다(§4-3 논리) — map25·fit_sim·실측 표본을 보존해야 2027-01 재개 시 재측정이 불필요하다. 툴은 /^DEAD/i를 필터하므로 후보 목록에서는 사라진다. | [2026-08-20 14시] ⭐ 이 건은 **「원문 미확인」을 미결 사유로 계속 끌지 않기로 결정**한 사례다 — as.com 차단은 회차를 더 써도 해소되지 않으므로, 릴레이 전수 추적으로 닫는다. Fotmob 라벨 날짜가 우리 판정보다 늦다는 사실만으로는 복원 근거가 되지 않는다는 것을 이 건이 실증한다(라벨은 리드 전용).');
INSERT INTO transfer_targets VALUES(143,'CHE','2026-summer','Pep Chavarría','차바리아','차바리아',80,NULL,'Rayo Vallecano','LB','LB','CONFIRMED','2026-08-12','510009210093100X510053100',NULL,NULL,39,6.799999999999999823,'fb_att_wb','Support','fb_att_wb','Support',0.8900000000000000133,'[2026-08-12 상향] Romano **"here we go"**(1티어, 원트윗 status 2085475147692061073, **2026-08-06 22:16**) — 첼시가 라요 바예카노와 합의, **€19m 고정 + €2m 애드온**. 후속 트윗(2085617184093446637, 08-07)에서 **메디컬·계약 서명을 위해 잉글랜드 이동**. Sky 수석기자 Kaveh Solhekol(1티어, 08-05)도 £16.3m+애드온으로 병행 보도. ⚠️ **어제 기록한 €25m은 Fotmob 추정치였다 — 실제는 €19m+€2m**. [전술 근거] Sky·The Athletic 공통 서술: **공을 앞으로 몰고 나가는 유형**의 좌측백이라 ''풀백이 볼을 전진시키라''는 알론소 지시에 부합. 포지션은 **하토의 백업·경쟁**이며 하토가 개막 주전 유력 — 주전 결손 메우기가 아니라 로테이션 보강이다. 쿠쿠렐라(→레알 £51.7m) 이탈의 대체. [경쟁구도] 경쟁 클럽 보도 0건, 첼시 단독. [2026-08-13 CONFIRMED] **첼시 구단 공식 발표 확인** — chelseafc.com 전용 발표 기사, **2031년까지 계약**. 어제 달아둔 "구단 공식 미확인" 캐비앗 해소. 이적료 €19m 고정 + €2m 애드온이 공식 보도로 재확인됐다(Romano 수치와 일치). 하토 백업·경쟁 구도 유지.','Fabrizio Romano 원트윗 status 2085475147692061073 (2026-08-06 22:16, "here we go") + status 2085617184093446637 (08-07 메디컬) ; Sky Sports Kaveh Solhekol (2026-08-05) ; The Athletic (08-05) ; 리드 Fotmob teamIds=8455 ; https://www.chelseafc.com/en/news/article/pep-chavarria-signs-for-chelsea (구단 공식)','HIGH — 1티어 3개 독립 확인(Romano 원트윗 2건 + Sky 수석기자). §2-0 발행일 검증 통과: 본문 나이 **28세**가 실제와 일치하고 병기 상황(쿠쿠렐라 레알행, 하토가 유일 좌측백, 알론소 부임)이 전부 26/27 창과 정합. 트윗 status ID로 발행 시각까지 확정했다. ⚠️ **CONFIRMED 아님** — 첼시 구단 공식 발표를 오늘까지 확인하지 못했다(08-11 시점 ''발표 임박''). 다음 회차 CONFIRMED 전환 1순위. ⚠️ 실측 PENDING — SofaScore 55경기 수집은 완료했으나 슬롯 판정·집계는 미수행. | [실측 완료 2026-08-12] SofaScore 25/26 전수 55경기 중 45분+ 39경기 집계. **39/39 전 경기 좌측 우세**(좌2컬럼 0.93·우2 0.00)라 좌우 혼입 없음 — 만잠비형 함정(obs#156) 해당 없음. ⚠️ 표본은 **라요 바예카노** 소속이고 첼시·알론소 체제가 아니다(obs#157).');
INSERT INTO transfer_targets VALUES(144,'LIV','2026-summer','Bradley Barcola','바르콜라','바르콜라',81,NULL,'PSG','LW','LW','MEDIUM-HIGH','2026-08-21','46211X5111411013100110000',NULL,NULL,39,7.089999999999999858,'w_wideplm','Build-Up','w_wideplm','Build-Up',0.9060000000000000275,unistr('[2026-08-12 상향] Romano(1티어, 08-10): **"리버풀이 공식 구단 간 협상을 시작했다"** · **"매일 협상 중(active talks in daily talks)"** · **"개인 조건은 전혀 문제가 아니다"**. Sky 원기사도 확정 — **08-07 Vinny O''Connor·Amar Mehta**(예비 회담 완료, PSG 평가액 £145m) 및 **07-29**(오프닝 오퍼 준비). ⚠️ Fotmob 라벨 ''Sky Sports/08-08''은 **출처는 정확, 날짜가 하루 오차**였다. 금액: 리버풀 ~€100m(£86m) → BBC 기준 £100m까지 상향 의사 vs PSG 요구 **€150m**(초기 €170m). 선수는 PSG 재계약을 거부했고 이라올라가 출전시간을 약속, 이적 희망 명확. [경쟁구도] 아스날 하이잭설은 The Sun(3티어) 단독이라 채택 불가 — **리버풀 단독 우위**. PSG는 Akliouche 영입 합의(08-01 Romano, £42.8m)로 스쿼드가 포화돼 방출 여건은 갖춰졌다. [2026-08-13 단계 변화 없음 — §2-0 함정 회피] 오늘 검색 상위를 "리버풀 £98.5m(€115m) **입찰 제출**" 헤드라인이 도배하나 추적 결과 **전부 L''Équipe(Loïc Tanzi) 08-07 보도의 재인용**이고 원문조차 "제출할 예정(set to submit)"이었다. ⭐ 그 뒤 **Romano(1티어) 08-10이 명시적으로 부인** — "리버풀은 PSG에 **공식 입찰을 보내지 않았다**. 공식 구단 간 협상을 시작하고 숫자를 제시(indicated)했을 뿐이며 PSG 요구액과는 여전히 멀다." 08-10 > 08-07이므로 **Romano 판이 유효**하다. ⚠️ ESPN(1티어) "Liverpool to bid for Barcola"도 **07-29자**였다. **신규 사실(단계 변화 아님)**: **알-켈라이피 PSG 회장이 08-12 슈퍼컵(PSG 2-1 아스톤 빌라) 직후 Canal+에 직접 발언** — "떠날지는 말할 수 없다. 오늘은 PSG 선수다. 두고 보자." 매각 부인이 아니라 **문을 열어둔 비확약 발언**이다. 금액 구도 불변: 리버풀 €100m대 vs PSG €150m 초과 요구. [2026-08-14 17시 — HIGH 유지, 1티어 신규 근거] **Romano 08-14 07:12 UK: 선수와 구두 합의(verbal agreement), ''선수는 가고 싶어 하고 리버풀은 강하게 밀어붙일 준비가 됐다. 딜은 살아 있다.''** 병행 Schira(2티어) €125m(£106m)·2032년 계약. ⛔ **구단 간 합의는 여전히 없다** — 리버풀 £120m vs PSG £145m. 알-켈라이피: ''우린 조용히 일한다.'' ⛔ 크로스체크 기각: DaveOCKOP발 ''€128m 원칙 합의''와 이를 받은 TEAMtalk/Football365 헤드라인은 **Romano가 직접 부인**(''아무것도 합의되지 않았고 최종 단계도 아니다'') — 3티어 단독이라 채택 불가. [경쟁구도] 리버풀 우위(단독 협상), 아스날은 모니터링만. [2026-08-14 21시 — HIGH 유지, 근거 보강(단계 전진은 아님)] 17시 회차의 Romano 08-14 07:12 UK(선수 구두 합의) **이후** 나온 신규 근거 3건: ⑴ Romano ''here we go'' — PSG↔아약스 **Mika Godts €55m 구두 합의**(트윗 status 2088223309108265216 = 스노플레이크 역산 08-14 11:16:48 UTC), L''Équipe 병행 확인. 08-13 18:02 UTC HWG로 확정된 **페란 토레스 €50m**(08-14 메디컬)와 합쳐 PSG는 아클리우셰·토레스·곳츠까지 **대체 자원을 선확보**했다. ⑵ TeamTalk 단독(Graeme Bailey) 08-14 10:15 UK: **PSG가 리버풀에 호가를 낮출 의사가 있다고 통보** — 착지 예상 약 £125m(PSG £145m ↔ 리버풀 £100~120m). ⑶ Ben Jacobs 08-12: 토레스+곳츠 합류 시 PSG 윙어가 9명이 되어 바르콜라 이탈이 사실상 보장된다. ⛔ **공식 입찰·구단 합의는 여전히 0건**이라 상향 근거는 아니다. [경쟁구도] 아스날은 모니터링뿐(Ornstein ''능동적 움직임 없음'') → **리버풀 사실상 단독 협상**, 남은 변수는 금액이다. [2026-08-15 재확인 — HIGH 유지, **새 단계 0건**] 08-14 12:00 UTC 이후 새 1~2티어 진전 보도가 없다(프랑스 매체 최신분도 08-07~08-14 범위, 08-15자 신규 0건). 유지되는 사실관계: 선수 구두 합의(Romano 08-14) · PSG 호가 인하 의사(TeamTalk 08-14 10:15, 착지 예상 £125m) · 리버풀 상한 £120m ↔ PSG £145~150m. Romano 최신 종합: 리버풀은 창 마감까지 **윙어 2명**을 원하며 각포가 나가면 바르콜라 외 한 자리가 더 남는다. `last_news_date`는 08-14를 유지한다(재확인 날짜로 밀지 않는다 — §4-3 함정). [2026-08-16 재확인 — HIGH 유지 / ⭐**1티어 반증을 처음 확보했다**] ⛔ 공식 입찰·구단 합의는 오늘도 0건이고 **새 단계 2일째 0**이다. ⭐ **The Athletic / James Pearce(1티어)**: €115m 입찰설을 **리버풀 시니어 구단 소식통이 부인**했다 — ''PSG가 €170m를 요구하는 상황에서 그런 오퍼는 무의미했을 것''. ⇒ 어제는 기사 ID 정렬(정황)만으로 기각했는데 **이제 1티어 직접 부인이 붙는다**. **Football Insider(Pete O''Rourke, 2티어) 08-15 18:00 UTC** — 마지막 스캔 이후 유일한 신규 항목: PSG가 요구액을 낮출 의향, 리버풀 낙관, **최근 수 주간 협상 교착**, 공식 입찰 없음. ⚠️ 여기서 리버풀 목표가가 **''£100m에 근접한 선''** 으로 적혀 우리가 가진 £120m 상한·TeamTalk £125m 착지 전망보다 **낮다** — 금액 축 3분기다. PSG 회장 알켈라이피: ''협상 중'', 떠날지는 ''말할 수 없다''. [2026-08-16 21시 — HIGH 유지, ⛔새 단계 3일째 0] 구간 내 최신 **ESPN 08-16 10:32 BST**도 "**preliminary talks only, no bid submitted**", PSG 요구 약 **€150m**으로 적는다. ⚠️ **금액 축이 3분기에서 4분기로 늘었다** — Pearce/FI **£100m 근접** ↔ Romano **£120m 초과 용의·£145m 불가** ↔ TeamTalk(Bailey) **PSG가 £125m에 승인 전망** ↔ ESPN/PSG **€150m** ↔ Schira **€125m(£106m) 근접**. **하한과 상한이 £45m 벌어져 있다.** [데드라인] 창 마감 09-01까지 16일, 개막 뉴캐슬 원정 **08-23**이 사실상 1차 시한이다. [2026-08-17 — HIGH 유지 / ⭐금액 축이 처음으로 하향 수렴했고 PSG 측 신호가 붙었다] ⛔ **공식 입찰·구단 합의는 4일째 0건**이다. 개막 뉴캐슬 원정(**08-23 15:30 UTC**)까지 6일. ⭐ **BBC Sport(1티어) 08-16 21:30 UTC(Joe Rindl)**: 바르콜라가 **Trophée des Champions 스쿼드에서 제외**됐고(Lens 1-0 PSG), **리버풀 지불 용의를 「somewhere in the region of £100m」** 으로 적는다. 08-12 UEFA 슈퍼컵에서도 미출전 교체였다. ⭐ **Luis Enrique 온더레코드**(경기 전 기자회견): 「**When a player doesn''t have a smile coming here, it''s better to seek a solution**」 — 이적 자체는 「창이 끝나면 말하겠다」로 함구. ⇒ **어제 4분기였던 금액 축의 최하단(£100m 근접)을 1티어가 지지**하고, 상단(£120m·£125m·€150m)에는 구간 내 1티어 지지가 없다.\u000a⛔⭐ **[2026-08-18 HIGH → MEDIUM-HIGH 하향]** **The Athletic(1티어) 08-18: 「not currently progressing」** + 「PSG가 **약 £145m 평가액을 내려야** 리버풀이 거래할 수 있다」. 이전 Athletic 보도는 「양 클럽이 아직 크게 떨어져 있고 리버풀이 **철수를 고려해야 할 수도**」였다. **공식 입찰·구단 합의는 5일째 0건**이고 개막(08-23 뉴캐슬 원정)까지 5일, 창 마감까지 14일이다. ⇒ §2 등급표의 HIGH 요건(**1티어가 협상/합의 단계를 보도**)이 **1티어 본인에 의해 부정**됐다. MEDIUM-HIGH는 유지된다 — 1티어가 **관심 자체는 확인**하고 2티어 복수(Le Parisien 08-18 「PSG가 €150m 이하에 귀를 열 수 있다」 · L''Équipe 「리버풀이 구체적 오퍼를 준비 중, 주말까지 제출 예상」)가 협상을 보도한다. [경쟁구도] 아스날 **관심**(Sky 08-07 1티어, 비니시우스 실패 후) · 바이에른 **접근 후 거절됨**(ESPN) — 둘 다 리버풀보다 뒤다. **리버풀 우위 유지.**\u000a⭐ **[2026-08-19 21시 — MEDIUM-HIGH 유지 / 개인 조건 축이 1티어로 굳었고 PSG 호가가 내려왔다]**\u000a**Romano(1티어)**: 「리버풀은 바르콜라와 **개인 조건 구두 합의(verbal agreement on personal terms)** 상태이며 **가속을 원한다**」.\u000a⇒ 09시 회차가 분해한 「오퍼 제출 주장 3건」과 **다른 축이다** — 부정된 것은 클럽 간 오퍼였고, **개인 조건 합의는 부정되지 않았다.**\u000a**호가 하향**: PSG 요구선이 **£145m → £125m(€146m)** 으로 내려왔다(Graeme Bailey + Alex Crook). 리버풀 제시 **€115m**, 상한 **€140m**.\u000a⇒ 격차가 **€146m ↔ €115m(상한 €140m)** 로 좁혀졌다. 단 09시 기록대로 **호가는 €170/150/146/145/140로 갈리므로 단일값 미채택.**\u000a⭐ **PSG 측 구조 압력이 커졌다** — PSG가 **Mika Godts €45m(아약스)** 를 영입해 **아클리우셰·페란 토레스와 합쳐 공격진에 €150m**을 투입했고,\u000a바르콜라는 **슈퍼컵(vs 빌라)에서 미출전 교체**였다. **루이스 엔리케 공개 발언**: 「선수가 행복하지 않다면 **다른 해법을 찾는 게 낫다**」.\u000a[경쟁구도] **리버풀 우위·사실상 단독** — 아스날 링크는 관심 단계이고 첼시·시티·맨유·바이에른은 「상황 공유」 수준이다.\u000a⛔ **HIGH 미충족 근거**: 클럽 간 합의 0 · 금액 격차 €31m(상한 적용 시 €6m) · PSG는 매각 의무 없음. | [2026-08-20 14시] ⭐⭐ **어제 보류한 발행일 확정을 완료했다 — Romano 발언은 08-13 유튜브 재사용이 아니라 08-19 신규다.** 원 venue는 **GiveMeSport**(유튜브가 아님)이고, 릴레이 트윗 2건의 스노플레이크가 독립적으로 시각을 고정한다: LFCTransferRoom 2090079506111283309 = **08-19 14:12:40 UTC**(「via @GiveMeSport」 명기) · AnfieldAgenda 2090080166428954827 = **08-19 14:15:18 UTC**. 2분 38초 간격의 서로 다른 계정이 같은 발언을 릴레이 ⇒ 08-13 유튜브 발언(€200m 최초)과 **별개 회차**다. ⭐ **원출처 오염 검사 통과** — F365의 「Today」 항목이 Romano/GiveMeSport로 귀착하고 **Foot01 / Abdellah Boulma 경로가 아니다**(그 3티어 건 「€135m 개선 입찰·PSG €140m 수용」은 기각 유지). Romano 원문: 「negotiations and discussions on a **daily basis** between PSG and Liverpool… it''s about reaching a financial agreement, but **a deal is on**」 + 「pushing to make it happen as soon as possible」. ⛔ **정식 입찰 제출 언급은 여전히 0건**이라 HIGH 불가. ⭐ 구단 공식 MEDIA WATCH(08-18, 원문 The Standard) 경유 보강: **PSG가 호가를 낮췄고**, 선수가 안필드행에 열려 있고, **개인 조건은 문제 없을 전망**이며, 양 측면 모두 소화 가능으로 평가된다. 아스날도 링크. | [2026-08-20 21시] ⭐⭐ **프랑스어가 가짜 신규 진전 1건을 제거했다.** 영어권(football365 「€115m bid confirmed」·TEAMtalk 「latest official offer is €115m」)이 현재값으로 제시하는 €115m은 **L Equipe 08-07 수치**다 — CulturePSG 08-07 17:20 CEST(Jean Chemarin)가 원 시각을 고정하고 제목이 「avance de 15 M€」다(구두 약 €100m 거절 → 공식 €115m). **13일 과거값을 현재로 제시한 것이다.** ⇒ **정식 입찰의 최신은 여전히 08-07 €115m이고 그 이후 1~2티어 신규 입찰 0건.** ⭐ 발행일 양성 대조: L Equipe 원문이 accord de principe를 「리버풀 경영진 및 **신임 감독 이라올라**와의 대화 후」로 적어 현 창 자료임이 확정된다. RMC: 랑스전 완전 제외는 징계가 아니라 **이적 전 리스크 회피**이고 해결 전까지 계속 보호된다. **아스날 축은 배제**(클럽 간 대화 0건, 선수 우선순위는 리버풀). | [2026-08-21] ⭐ **RMC(프랑스 1티어) 신규**: 선수-리버풀 **5년 계약(2031-06) 개인합의** · 클럽 간 협상 계속 · **새 오퍼가 이번 주 예정** · 「tout le monde s attend aujourd hui à ce qu un accord soit conclu」. L Équipe: 원칙 합의는 리버풀 경영진 **및 이라올라와의 면담 후** 이뤄졌다. ⭐⭐ **자금 구조가 처음 특정됐다** — 리버풀은 **매각 2건으로 약 €120m을 만들어**(그중 **각포 최소 €80m 요구**) 오퍼를 올려 PSG 기대치 **€150m**에 접근하려 한다. PSG 측: 수페르컵(빌라전)·트로페 데 샹피옹(랑스전) 모두 제외 · 재계약 거부(계약 2028) · Godts 영입이 방출 선행 신호 · Romano 「confidence absolutely growing」.'),'Fabrizio Romano (2026-08-10) via football365.com/news/bradley-barcola-liverpool-paris-saint-germain-fabrizio-romano-transfer-update ; Sky Sports Vinny O''Connor·Amar Mehta (2026-08-07) skysports.com/football/news/11669/13570766 ; Sky (2026-07-29) 11095/13567997 ; Sky 영상 Mark McAdam (08-11) · R